-- Read-only result evidence; does not change marks or approval rules.
create or replace function public.unimis_review_evidence136(p_result uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare r public.course_results;inst uuid;dep uuid;per uuid;manager boolean;items jsonb;checks jsonb:='[]'::jsonb;weights numeric;computed numeric;missing int;invalid int;band record;summary jsonb;scheme uuid;
begin
 select * into r from public.course_results where id=p_result;
 if r.id is null then raise exception 'Result not found';end if;
 inst:=r.institution_id;manager:=public.unimis_review_manager130(inst);
 if not manager and not exists(select 1 from public.unimis_batch_results130 br where br.result_id=r.id and public.unimis_batch_access130(br.batch_id)) then raise exception 'Result review access denied';end if;
 select p.department_id,spr.academic_period_id into dep,per from public.student_course_registrations scr join public.student_period_registrations spr on spr.id=scr.period_registration_id and spr.institution_id=inst join public.student_programme_enrolments en on en.id=spr.programme_enrolment_id and en.institution_id=inst join public.programmes p on p.id=en.programme_id and p.institution_id=inst where scr.id=r.student_course_registration_id and scr.institution_id=inst;
 select coalesce(jsonb_agg(jsonb_build_object('name',ai.name,'maximum',ai.max_score,'weight',ai.weight_percent,'raw',sc.raw_score,'stored_weighted',sc.weighted_score,'contribution',round(sc.raw_score/nullif(ai.max_score,0)*ai.weight_percent,4),'score_status',sc.status,'entered_at',sc.entered_at,'entered_by',sc.entered_by) order by ai.name),'[]'::jsonb),coalesce(sum(ai.weight_percent),0),sum(sc.raw_score/nullif(ai.max_score,0)*ai.weight_percent),count(*) filter(where sc.raw_score is null),count(*) filter(where ai.max_score<=0 or sc.raw_score<0 or sc.raw_score>ai.max_score or sc.status='withheld' or sc.weighted_score is not null and abs(sc.weighted_score-sc.raw_score/nullif(ai.max_score,0)*ai.weight_percent)>0.02)
 into items,weights,computed,missing,invalid
 from public.assessment_items ai left join public.assessment_scores sc on sc.assessment_item_id=ai.id and sc.student_course_registration_id=r.student_course_registration_id and sc.institution_id=inst
 where ai.institution_id=inst and ai.course_offering_id=r.course_offering_id and ai.status<>'cancelled';
 if jsonb_array_length(items)=0 then checks:=checks||jsonb_build_array('Assessment breakdown unavailable: final mark alone cannot verify its source.');end if;
 if abs(weights-100)>0.01 then checks:=checks||jsonb_build_array('Assessment weights do not total 100%.');end if;
 if missing>0 then checks:=checks||jsonb_build_array(missing||' assessment score(s) missing.');end if;
 if invalid>0 then checks:=checks||jsonb_build_array(invalid||' assessment score(s) out of range, withheld or inconsistent with their stored contribution.');end if;
 if computed is not null and (r.total_score is null or abs(round(computed,2)-r.total_score)>0.02) then checks:=checks||jsonb_build_array('Computed assessment total differs from recorded final mark.');end if;
 scheme:=coalesce(r.grading_scheme_id,public.unimis_resolve_grading_scheme(inst,r.course_offering_id));
 select * into band from public.grade_bands gb where gb.institution_id=inst and gb.grading_scheme_id=scheme and r.total_score between gb.min_score and gb.max_score order by gb.min_score desc limit 1;
 if band.letter_grade is null then checks:=checks||jsonb_build_array('No matching grade band for the recorded mark.');
 elsif r.letter_grade is distinct from band.letter_grade or r.grade_point is distinct from band.grade_point or r.passed is distinct from band.is_pass then checks:=checks||jsonb_build_array('Recorded grade, grade point or pass status differs from the applicable grade band.');end if;
 if r.submitted_by is null or r.submitted_at is null then checks:=checks||jsonb_build_array('Submission identity or date is missing.');end if;
 with cohort as (
 select scr.id,cr.total_score,cr.passed,cr.letter_grade,cr.result_status from public.student_course_registrations scr join public.student_period_registrations spr on spr.id=scr.period_registration_id and spr.institution_id=inst join public.student_programme_enrolments en on en.id=spr.programme_enrolment_id and en.institution_id=inst join public.programmes p on p.id=en.programme_id and p.institution_id=inst left join public.course_results cr on cr.student_course_registration_id=scr.id and cr.institution_id=inst
 where scr.institution_id=inst and scr.course_offering_id=r.course_offering_id and scr.status not in ('dropped','withdrawn') and p.department_id=dep and spr.academic_period_id=per and (manager or exists(select 1 from public.unimis_batch_results130 br where br.result_id=cr.id and public.unimis_batch_access130(br.batch_id))))
 select jsonb_build_object('registered',count(*),'submitted',count(*) filter(where result_status='submitted'),'approved',count(*) filter(where result_status='approved'),'published',count(*) filter(where result_status='published'),'missing_results',count(*) filter(where result_status is null or result_status='draft'),'average',round(avg(total_score),2),'passes',count(*) filter(where passed),'failures',count(*) filter(where passed=false),'graded',count(*) filter(where passed is not null),'grade_distribution',coalesce((select jsonb_agg(to_jsonb(g)) from (select letter_grade grade,count(*) students from cohort group by letter_grade order by letter_grade)g),'[]'::jsonb)) into summary from cohort;
 return jsonb_build_object('result',to_jsonb(r),'student',(select jsonb_build_object('number',s.student_number,'name',concat_ws(' ',s.first_name,s.middle_name,s.last_name)) from public.students s where s.id=r.student_id and s.institution_id=inst),'course',(select jsonb_build_object('code',c.code,'name',c.name) from public.course_offerings o join public.courses c on c.id=o.course_id and c.institution_id=inst where o.id=r.course_offering_id and o.institution_id=inst),'department',(select name from public.departments where id=dep and institution_id=inst),'summary_scope',case when manager then 'Registered home-department cohort for this course and semester' else 'Accessible batch results in this home department, course and semester' end,'items',items,'weight_total',weights,'computed_total',round(computed,2),'checks',checks,'scheme',(select to_jsonb(gs) from public.grading_schemes gs where gs.id=scheme and gs.institution_id=inst),'grade_bands',coalesce((select jsonb_agg(to_jsonb(gb) order by gb.min_score desc) from public.grade_bands gb where gb.grading_scheme_id=scheme and gb.institution_id=inst),'[]'::jsonb),'expected_grade',to_jsonb(band),'submitted_email',(select email from auth.users where id=r.submitted_by),'summary',summary,'history',coalesce((select jsonb_agg(to_jsonb(h) order by h.action_at desc) from public.result_approval_history h where h.course_result_id=r.id and h.institution_id=inst),'[]'::jsonb));
end $$;
revoke all on function public.unimis_review_evidence136(uuid) from public,anon;
grant execute on function public.unimis_review_evidence136(uuid) to authenticated;
